from solution import allocate


def test_examples():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_negative():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_all_zero_raises():
    try:
        allocate(10, [0, 0])
    except ValueError:
        return
    assert False


def test_all_zero_total_zero_raises():
    try:
        allocate(0, [0, 0])
    except ValueError:
        return
    assert False


def test_empty_weights_raises():
    try:
        allocate(0, [])
    except ValueError:
        return
    assert False


def test_zero_total():
    assert allocate(0, [1, 2]) == [0, 0]


def test_large_precision():
    total = 10**18 + 1
    w = [1, 1, 1]
    r = allocate(total, w)
    assert sum(r) == total
    # exact: 333333333333333333 each remainder 1/3 ... total = 3q+1 -> first gets extra
    q = total // 3
    assert r == [q + 1, q, q]


def test_large_weights_exact():
    total = 10**15
    w = [10**15 + 1, 10**15 + 2, 10**15 + 3]
    r = allocate(total, w)
    s = sum(w)
    fl = [total * x // s for x in w]
    rem = [(total * x) % s for x in w]
    left = total - sum(fl)
    order = sorted(range(3), key=lambda i: (-rem[i], i))
    for i in order[:left]:
        fl[i] += 1
    assert r == fl


def test_tie_exact_large():
    total = 10**17 + 3
    w = [1] * 7
    r = allocate(total, w)
    assert sum(r) == total
    q, m = divmod(total, 7)
    assert r == [q + 1] * m + [q] * (7 - m)


def test_remainder_ordering():
    # shares: 10*1/6=1.67, 10*2/6=3.33, 10*3/6=5
    assert allocate(10, [1, 2, 3]) == [2, 3, 5]


def test_single():
    assert allocate(7, [5]) == [7]
    assert allocate(-7, [5]) == [-7]

from solution import allocate


def test_examples():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_negative():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_all_zero_raises():
    try:
        allocate(10, [0, 0])
    except ValueError:
        return
    assert False


def test_zero_total_all_zero_weights_raises():
    try:
        allocate(0, [0, 0])
    except ValueError:
        return
    assert False


def test_zero_total():
    assert allocate(0, [1, 2]) == [0, 0]


def test_large_precision():
    total = 10**18 + 1
    w = [1, 1, 1]
    r = allocate(total, w)
    assert sum(r) == total
    assert r == [333333333333333334, 333333333333333334, 333333333333333333]


def test_large_exact_floor():
    total = 10**17 + 3
    r = allocate(total, [1, 1])
    assert r == [50000000000000002, 50000000000000001]


def test_large_weights_precision():
    total = 10**6
    w = [10**20 + 1, 10**20 + 2, 10**20 + 3]
    r = allocate(total, w)
    assert sum(r) == total
    assert r == [333333, 333333, 333334] or r == [333334, 333333, 333333]
    # exact: remainders increase with weight, so last gets extra
    assert r == [333333, 333333, 333334]


def test_tie_earlier():
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_remainder_order():
    # shares: 1.0*... total 10 weights [1,2,7] -> 1,2,7 exact
    assert allocate(10, [1, 2, 7]) == [1, 2, 7]
    # total 7, weights [1,2]: 2.333, 4.667 -> 2,4 +1 to second
    assert allocate(7, [1, 2]) == [2, 5]


def test_single():
    assert allocate(-7, [3]) == [-7]
